package cluster

import (
	"bytes"
	"errors"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strconv"
)

// Section is the name of the peers section janusd generates: what a
// stick table names ("peers janus") to be replicated, cluster or not.
const Section = "janus"

// PeersFile is the generated file's name, next to haproxy.cfg: HAProxy
// reads it as a second -f.
const PeersFile = "janus-peers.cfg"

// LocalBindAddress is where a node that is no member binds its peers
// listener: nothing reaches it, and the next HAProxy process still
// learns the stick tables from the one it replaces (the local resync
// needs a listener - without one, HAProxy 3.4 even crashes the old
// process on a reload).
const LocalBindAddress = "127.0.0.1"

// PeersConfig renders HAProxy's peers section for what the node knows:
// its members with their addresses, over TLS with the member
// certificate - or, for a node that is no member, itself alone. Two
// process variables name the cluster and the member for the operator's
// rules (proc.janus_cluster is unset on a node that is no member).
func (s *Store) PeersConfig() []byte {
	s.mu.RLock()
	defer s.mu.RUnlock()
	local := s.Hostname()
	if s.m != nil {
		local = s.m.Member
	}
	var b bytes.Buffer
	b.WriteString("# Generated by janusd from the cluster's composition (docs/cluster.md)\n")
	b.WriteString("# - not editable: ClusterSet changes it. HAProxy runs with it as a second\n")
	b.WriteString("# -f after haproxy.cfg, and -L " + local + ".\n")
	b.WriteString("global\n")
	if s.m != nil {
		b.WriteString("    set-var proc.janus_cluster str(" + s.m.ID + ")\n")
	}
	b.WriteString("    set-var proc.janus_member str(" + local + ")\n")
	b.WriteString("\npeers " + Section + "\n")
	if s.m == nil {
		b.WriteString("    bind " + net.JoinHostPort(LocalBindAddress, strconv.Itoa(DefaultPeersPort)) + "\n")
		b.WriteString("    server " + local + "\n")
		return b.Bytes()
	}
	tls := "ssl crt " + filepath.Join(s.Dir, MemberFile) + " ca-file " + filepath.Join(s.Dir, CAFile) + " verify required"
	port := strconv.Itoa(s.m.PeersPort)
	self := s.m.Self()
	b.WriteString("    bind " + net.JoinHostPort(self.Address, port) + " " + tls + "\n")
	b.WriteString("    default-server " + tls + "\n")
	b.WriteString("    server " + local + "\n")
	for _, p := range s.m.Peers() {
		b.WriteString("    server " + p.Name + " " + net.JoinHostPort(p.Address, port) + " verifyhost " + p.Name + "\n")
	}
	return b.Bytes()
}

// WritePeersFile writes PeersConfig to path, durably, and reports
// whether it changed - the caller reloads HAProxy then.
func (s *Store) WritePeersFile(path string) (changed bool, err error) {
	want := s.PeersConfig()
	have, err := os.ReadFile(path)
	if err == nil && bytes.Equal(have, want) {
		return false, nil
	}
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return false, fmt.Errorf("read %s: %w", path, err)
	}
	if err := writeDurable(filepath.Dir(path), filepath.Base(path), want, 0o644); err != nil {
		return false, fmt.Errorf("write %s: %w", path, err)
	}
	return true, nil
}

// BindPort is the port the generated section binds: the cluster's, or
// DefaultPeersPort for a node that is no member - what the operator's
// own bind lines must leave alone (internal/haproxy's policy).
func (s *Store) BindPort() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.m != nil {
		return s.m.PeersPort
	}
	return DefaultPeersPort
}
